import './AmudDisplay.css';

interface AmudDisplayProps {
  amud: Amud | null;
  showNikud: boolean;
  wordGap: number;
  isLoading: boolean;
}

export const AmudDisplay: React.FC<AmudDisplayProps> = ({
  amud,
  showNikud,
  wordGap,
  isLoading
}) => {
  if (isLoading) {
    return (
      <div className="amud-display loading">
        <LoadingSpinner message="טוען עמוד..." size="large" />
