  return (
    <div className="amud-display" data-amud={amud.amud}>
      <div className="amud-content">
        {amud.lines.map((line) => (
          <TextLine
            key={line.number}
            line={line}
            showNikud={showNikud}
            wordGap={amud.amud === 78 ? 0 : wordGap}
          />
        ))}
      </div>
    </div>
  );
};

