  1→import React, { useState, useEffect, useRef } from 'react';
  2→import { seforim, parshios, aliyanames, aliyos } from '../../data/parshadata';
  3→import './ParshaNavigation.css';
  4→
  5→interface ParshaNavigationProps {
  6→  onParshaSelect?: (sefer: string, parsha: string, aliya?: number) => void;
  7→  currentParsha?: string;
  8→  currentSefer?: string;
  9→  currentAliya?: number;
 10→  isOpen: boolean;
 11→  onToggle: () => void;
 12→}
 13→
 14→export const ParshaNavigation: React.FC<ParshaNavigationProps> = ({
 15→  onParshaSelect,
 16→  currentParsha,
 17→  currentSefer,
 18→  currentAliya,
 19→  isOpen,
 20→  onToggle
 21→}) => {
 22→  const [selectedSefer, setSelectedSefer] = useState<string>(currentSefer || seforim[0]);
 23→  const [selectedParsha, setSelectedParsha] = useState<string>(currentParsha || '');
 24→  const [showAliyos, setShowAliyos] = useState<boolean>(false);
 25→  const [searchTerm, setSearchTerm] = useState<string>('');
 26→  const [hoveredItem, setHoveredItem] = useState<string | null>(null);
 27→  const menuRef = useRef<HTMLDivElement>(null);
 28→
 29→  // Update selected items when current props change
 30→  useEffect(() => {
 31→    if (currentSefer && currentSefer !== selectedSefer) {
 32→      setSelectedSefer(currentSefer);
 33→    }
 34→    if (currentParsha && currentParsha !== selectedParsha) {
 35→      setSelectedParsha(currentParsha);
 36→      setShowAliyos(true);
 37→    }
 38→  }, [currentSefer, currentParsha, selectedSefer, selectedParsha]);
 39→
 40→  // Close menu when clicking outside
 41→  useEffect(() => {
 42→    const handleClickOutside = (event: MouseEvent) => {
 43→      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
 44→        if (isOpen) onToggle();
 45→      }
 46→    };
 47→
 48→    document.addEventListener('mousedown', handleClickOutside);
 49→    return () => document.removeEventListener('mousedown', handleClickOutside);
 50→  }, [isOpen, onToggle]);
 51→
 52→  // Filter parshios based on search term
 53→  const filteredParshios = selectedSefer 
 54→    ? parshios[selectedSefer as keyof typeof parshios].filter(parsha =>
 55→        parsha.includes(searchTerm) || parsha.toLowerCase().includes(searchTerm.toLowerCase())
 56→      )
 57→    : [];
 58→
 59→  const handleSeferSelect = (sefer: string) => {
 60→    setSelectedSefer(sefer);
 61→    setSelectedParsha('');
 62→    setShowAliyos(false);
 63→    setSearchTerm('');
 64→  };
 65→
 66→  const handleParshaSelect = (parsha: string) => {
 67→    setSelectedParsha(parsha);
 68→    setShowAliyos(true);
 69→    if (onParshaSelect) {
 70→      onParshaSelect(selectedSefer, parsha);
 71→    }
 72→  };
 73→
 74→  const handleAliyaSelect = (aliyaIndex: number) => {
 75→    if (onParshaSelect && selectedParsha) {
 76→      onParshaSelect(selectedSefer, selectedParsha, aliyaIndex + 1);
 77→    }
 78→    onToggle(); // Close menu after selection
 79→  };
 80→
 81→  const getCurrentAliyaData = () => {
 82→    if (selectedParsha && aliyos[selectedParsha as keyof typeof aliyos]) {
 83→      return aliyos[selectedParsha as keyof typeof aliyos];
 84→    }
 85→    return null;
 86→  };
 87→
 88→  return (
 89→    <>
 90→      {/* Backdrop */}
 91→      {isOpen && <div className="parsha-nav-backdrop" onClick={onToggle} />}
 92→      
 93→      {/* Menu Toggle Button */}
 94→      <button 
 95→        className={`parsha-nav-toggle ${isOpen ? 'active' : ''}`}
 96→        onClick={onToggle}
 97→        aria-label="Toggle Parsha Navigation"
 98→      >
 99→        <span className="hamburger-line"></span>
100→        <span className="hamburger-line"></span>
101→        <span className="hamburger-line"></span>
102→      </button>
103→
104→      {/* Navigation Menu */}
105→      <div 
106→        ref={menuRef}
107→        className={`parsha-navigation ${isOpen ? 'open' : ''}`}
108→      >
109→        <div className="parsha-nav-header">
110→          <h2>ניווט פרשיות</h2>
111→          <button className="close-button" onClick={onToggle}>
112→            ✕
113→          </button>
114→        </div>
115→
116→        <div className="parsha-nav-content">
117→          {/* Search Bar */}
118→          <div className="search-container">
119→            <input
120→              type="text"
121→              placeholder="חפש פרשה..."
122→              value={searchTerm}
123→              onChange={(e) => setSearchTerm(e.target.value)}
124→              className="search-input"
125→            />
126→            <span className="search-icon">🔍</span>
127→          </div>
128→
129→          {/* Current Selection Display */}
130→          {(currentSefer || currentParsha) && (
131→            <div className="current-selection">
132→              <span className="current-label">נבחר כעת:</span>
133→              <div className="current-path">
134→                {currentSefer && <span className="current-sefer">{currentSefer}</span>}
135→                {currentParsha && (
136→                  <>
137→                    <span className="separator">›</span>
138→                    <span className="current-parsha">{currentParsha}</span>
139→                  </>
140→                )}
141→                {currentAliya && (
142→                  <>
143→                    <span className="separator">›</span>
144→                    <span className="current-aliya">{aliyanames[currentAliya - 1]}</span>
145→                  </>
146→                )}
147→              </div>
148→            </div>
149→          )}
150→
151→          {/* Seforim Selection */}
152→          <div className="nav-section">
153→            <h3>ספרים</h3>
154→            <div className="seforim-grid">
155→              {seforim.map((sefer) => (
156→                <button
157→                  key={sefer}
158→                  className={`sefer-button ${selectedSefer === sefer ? 'selected' : ''} ${currentSefer === sefer ? 'current' : ''}`}
159→                  onClick={() => handleSeferSelect(sefer)}
160→                  onMouseEnter={() => setHoveredItem(sefer)}
161→                  onMouseLeave={() => setHoveredItem(null)}
162→                >
163→                  <span className="sefer-name">{sefer}</span>
164→                  <span className="sefer-count">
165→                    {parshios[sefer as keyof typeof parshios].length} פרשיות
166→                  </span>
167→                </button>
168→              ))}
169→            </div>
170→          </div>
171→
172→          {/* Parshios Selection */}
173→          {selectedSefer && (
174→            <div className="nav-section">
175→              <h3>פרשיות - {selectedSefer}</h3>
176→              <div className="parshios-grid">
177→                {filteredParshios.map((parsha) => (
178→                  <button
179→                    key={parsha}
180→                    className={`parsha-button ${selectedParsha === parsha ? 'selected' : ''} ${currentParsha === parsha ? 'current' : ''}`}
181→                    onClick={() => handleParshaSelect(parsha)}
182→                    onMouseEnter={() => setHoveredItem(parsha)}
183→                    onMouseLeave={() => setHoveredItem(null)}
184→                  >
185→                    <span className="parsha-name">{parsha}</span>
186→                    {aliyos[parsha as keyof typeof aliyos] && (
187→                      <span className="aliya-indicator">🔹</span>
188→                    )}
189→                  </button>
190→                ))}
191→              </div>
192→            </div>
193→          )}
194→
195→          {/* Aliyos Selection */}
196→          {showAliyos && selectedParsha && getCurrentAliyaData() && (
197→            <div className="nav-section">
198→              <h3>עליות - {selectedParsha}</h3>
199→              <div className="aliyos-grid">
200→                {aliyanames.map((aliyaName, index) => {
201→                  const aliyaData = getCurrentAliyaData();
202→                  const aliyaKey = (index + 1).toString();
203→                  const hasData = aliyaData && (aliyaData as any)[aliyaKey];
204→                  
205→                  if (!hasData) return null;
206→
207→                  return (
208→                    <button
209→                      key={index}
210→                      className={`aliya-button ${currentAliya === index + 1 ? 'current' : ''}`}
211→                      onClick={() => handleAliyaSelect(index)}
212→                      onMouseEnter={() => setHoveredItem(`${aliyaName}-${index}`)}
213→                      onMouseLeave={() => setHoveredItem(null)}
214→                    >
215→                      <span className="aliya-name">{aliyaName}</span>
216→                      <span className="aliya-range">
217→                        {(aliyaData as any)[aliyaKey]}
218→                      </span>
219→                    </button>
220→                  );
221→                })}
222→              </div>
223→            </div>
224→          )}
225→
226→          {/* Quick Actions */}
227→          <div className="nav-section quick-actions">
228→            <h3>פעולות מהירות</h3>
229→            <div className="quick-actions-grid">
230→              <button 
231→                className="quick-action-button"
232→                onClick={() => {
233→                  setSelectedSefer(seforim[0]);
234→                  setSelectedParsha(parshios[seforim[0] as keyof typeof parshios][0]);
235→                  if (onParshaSelect) {
236→                    onParshaSelect(seforim[0], parshios[seforim[0] as keyof typeof parshios][0], 1);
237→                  }
238→                  onToggle();
239→                }}
240→              >
241→                <span>🏠</span>
242→                התחלה
243→              </button>
244→              <button 
245→                className="quick-action-button"
246→                onClick={() => {
247→                  setSearchTerm('');
248→                  setSelectedSefer(seforim[0]);
249→                  setSelectedParsha('');
250→                  setShowAliyos(false);
251→                }}
252→              >
253→                <span>🔄</span>
254→                איפוס
255→              </button>
256→            </div>
257→          </div>
258→        </div>
259→      </div>
260→    </>
261→  );
262→};
