 1→import React, { useState, useEffect } from 'react';
 2→import './Toast.css';
 3→
 4→interface ToastProps {
 5→  message?: string;
 6→  type?: 'info' | 'success' | 'warning' | 'error';
 7→  duration?: number;
 8→  show?: boolean;
 9→  onHide?: () => void;
10→}
11→
12→export const Toast: React.FC<ToastProps> = ({
13→  message,
14→  type = 'info',
15→  duration = 3000,
16→  show = false,
17→  onHide
18→}) => {
19→  const [visible, setVisible] = useState(show);
20→
21→  useEffect(() => {
22→    setVisible(show);
23→  }, [show]);
24→
25→  useEffect(() => {
26→    if (visible && duration > 0) {
27→      const timer = setTimeout(() => {
28→        setVisible(false);
29→        onHide?.();
30→      }, duration);
31→
32→      return () => clearTimeout(timer);
33→    }
34→  }, [visible, duration, onHide]);
35→
36→  if (!visible || !message) return null;
37→
38→  return (
39→    <div className={`toast toast-${type} ${visible ? 'toast-show' : ''}`}>
40→      <div className="toast-content">
41→        <span className="toast-icon">
42→          {type === 'success' && '✓'}
43→          {type === 'info' && 'ℹ'}
44→          {type === 'warning' && '⚠'}
45→          {type === 'error' && '✗'}
46→        </span>
47→        <span className="toast-message">{message}</span>
48→      </div>
49→    </div>
50→  );
51→};
