 4→import './TextLine.css';
 5→
 6→interface TextLineProps {
 7→  line: Line;
 8→  showNikud: boolean;
 9→  wordGap: number;
10→}
11→
12→export const TextLine: React.FC<TextLineProps> = React.memo(({ line, showNikud, wordGap }) => {
13→  const containerRef = useRef<HTMLDivElement | null>(null);
14→  
15→  const processedFragments = useMemo(() => {
16→    return processHebrewText(line.fragments, showNikud, wordGap, line.layout);
17→  }, [line.fragments, showNikud, wordGap, line.layout]);
18→
19→  return (
20→    <div
21→      ref={containerRef}
22→      className={`text-line hebrew-text ${line.layout}`}
23→      data-line-number={line.number}
24→      style={wordGap > 0 ? { wordSpacing: `${wordGap * 2}px` } : undefined}
25→    >
26→      {processedFragments.map((fragment, index) => (
27→        <span
28→          key={index}
29→          className="text-fragment"
30→          dangerouslySetInnerHTML={{ __html: fragment }}
31→        />
32→      ))}
33→      
34→      {/* Right-side pasuk labels (red Hebrew letters) */}
35→      {line.meta.length > 0 && (
36→        <div className="labelright">
37→          {line.meta.map((metaItem, idx) => 
38→            metaItem.pasuk ? (
39→              <div key={idx} className="pasuk">
40→                {misparim[metaItem.pasuk - 1] || metaItem.pasuk.toString()}
41→              </div>
42→            ) : null
43→          )}
44→        </div>
45→      )}
46→      
47→      {/* Left-side aliyah labels */}
48→      {line.aliyot.length > 0 && (
49→        <div className="labelleft">
50→          {line.aliyot.map((aliyahNum, idx) => (
51→            <div key={idx} className="aliya">
52→              {aliyot[aliyahNum - 1] || aliyahNum.toString()}
53→            </div>
54→          ))}
55→        </div>
56→      )}
57→    </div>
58→  );
59→});
