  1→import React, { useEffect, useRef, useCallback, useMemo } from 'react';
  2→import { Amud } from '../../types';
  3→import { TextLine } from '../TextLine/TextLine';
  4→import { LoadingSpinner } from '../LoadingSpinner/LoadingSpinner';
  5→import './InfiniteAmudScroll.css';
  6→
  7→// Only render amudim within this many pages of the current view.
  8→// 10 pages in each direction = ~21 amudim mounted at a time vs 248.
  9→const RENDER_BUFFER = 10;
 10→
 11→interface InfiniteAmudScrollProps {
 12→  currentAmud: number;
 13→  totalAmudim: number;
 14→  showNikud: boolean;
 15→  wordGap: number;
 16→  isLoading: boolean;
 17→  data: Amud[];
 18→  targetLine?: number;
 19→  onAmudChange: (amud: number) => void;
 20→}
 21→
 22→export const InfiniteAmudScroll: React.FC<InfiniteAmudScrollProps> = ({
 23→  currentAmud,
 24→  totalAmudim,
 25→  showNikud,
 26→  wordGap,
 27→  isLoading,
 28→  data,
 29→  targetLine,
 30→  onAmudChange
 31→}) => {
 32→  const containerRef = useRef<HTMLDivElement>(null);
 33→  const isScrollingRef = useRef(false);
 34→  const scrollTimeoutRef = useRef<number | undefined>(undefined);
 35→
 36→  // Cleanup timeout on unmount
 37→  useEffect(() => {
 38→    return () => {
 39→      if (scrollTimeoutRef.current) {
 40→        window.clearTimeout(scrollTimeoutRef.current);
 41→      }
 42→    };
 43→  }, []);
 44→
 45→  // --- Render window: only mount amudim close to current ---
 46→  const currentIndex = useMemo(
 47→    () => data.findIndex(a => a.amud === currentAmud),
 48→    [data, currentAmud]
 49→  );
 50→
 51→  const renderStart = Math.max(0, currentIndex - RENDER_BUFFER);
 52→  const renderEnd = Math.min(data.length, currentIndex + RENDER_BUFFER + 1);
 53→
 54→  // Function to scroll to a specific amud and line
 55→  const scrollToAmudAndLine = useCallback((amudNumber: number, lineNumber?: number) => {
 56→    if (!containerRef.current) return;
 57→
 58→    if (scrollTimeoutRef.current) {
 59→      window.clearTimeout(scrollTimeoutRef.current);
 60→    }
 61→
 62→    isScrollingRef.current = true;
 63→
 64→    const amudElement = containerRef.current.querySelector(`[data-amud="${amudNumber}"]`);
 65→    if (!amudElement) {
 66→      isScrollingRef.current = false;
 67→      return;
 68→    }
 69→
 70→    let targetElement = amudElement;
 71→
 72→    if (lineNumber) {
 73→      const lineElement = amudElement.querySelector(`[data-line="${lineNumber}"]`);
 74→      if (lineElement) {
 75→        targetElement = lineElement;
 76→      }
 77→    }
 78→
 79→    targetElement.scrollIntoView({
 80→      behavior: 'auto',
 81→      block: 'center',
 82→      inline: 'nearest'
 83→    });
 84→
 85→    scrollTimeoutRef.current = window.setTimeout(() => {
 86→      isScrollingRef.current = false;
 87→    }, 150);
 88→  }, []);
 89→
 90→  // Scroll when currentAmud or targetLine changes
 91→  useEffect(() => {
 92→    if (currentAmud && data.length > 0) {
 93→      requestAnimationFrame(() => {
 94→        scrollToAmudAndLine(currentAmud, targetLine);
 95→      });
 96→    }
 97→  }, [currentAmud, targetLine, data.length, scrollToAmudAndLine]);
 98→
 99→  // Intersection Observer to detect which amud is currently visible
100→  useEffect(() => {
101→    if (!containerRef.current || isLoading) return;
102→
103→    const observer = new IntersectionObserver(
104→      (entries) => {
105→        if (isScrollingRef.current) return;
106→
107→        entries.forEach((entry) => {
108→          if (entry.isIntersecting && entry.intersectionRatio > 0.6) {
109→            const amudNumber = parseInt(entry.target.getAttribute('data-amud') || '0');
110→            if (amudNumber && amudNumber !== currentAmud) {
111→              onAmudChange(amudNumber);
112→            }
113→          }
114→        });
115→      },
116→      {
117→        root: null,
118→        rootMargin: '-40% 0px -40% 0px',
119→        threshold: [0.6]
120→      }
121→    );
122→
123→    const amudElements = containerRef.current.querySelectorAll('[data-amud]');
124→    amudElements.forEach((element) => observer.observe(element));
125→
126→    return () => observer.disconnect();
127→  }, [data, currentAmud, onAmudChange, isLoading]);
128→
129→  if (isLoading) {
130→    return (
131→      <div className="infinite-amud-scroll loading">
132→        <LoadingSpinner message="טוען עמודים..." size="large" />
133→      </div>
134→    );
135→  }
136→
137→  const hasAmud78 = data.some(amud => amud.amud === 78);
138→
139→  return (
140→    <div className={`infinite-amud-scroll ${hasAmud78 ? 'has-amud-78' : ''}`} ref={containerRef}>
141→      {data.map((amudData, index) => {
142→        const isInWindow = index >= renderStart && index < renderEnd;
143→
144→        if (!isInWindow) {
145→          // Lightweight placeholder — keeps scroll position stable
146→          return (
147→            <div
148→              key={amudData.amud}
149→              className="amud-placeholder"
150→              data-amud={amudData.amud}
151→            />
152→          );
153→        }
154→
155→        return (
156→          <div
157→            key={amudData.amud}
158→            className={`amud-display ${amudData.amud === currentAmud ? 'current' : ''}`}
159→            data-amud={amudData.amud}
160→          >
161→            <div className="amud-content">
162→              {amudData.lines.map((line) => (
163→                <div key={line.number} data-line={line.number}>
164→                  <TextLine
165→                    line={line}
166→                    showNikud={showNikud}
167→                    wordGap={amudData.amud === 78 ? 0 : wordGap}
168→                  />
169→                </div>
170→              ))}
171→            </div>
172→          </div>
173→        );
174→      })}
175→    </div>
176→  );
177→};
