  6→// Remove nikud (vowel points) from Hebrew text
  7→export const removeNikud = (text: string): string => {
  8→  // Hebrew vowel points range: U+05B0-U+05BC, U+05C1-U+05C2, U+05C4-U+05C5, U+05C7
  9→  const nikudRegex = /[\u05B0-\u05BC\u05C1\u05C2\u05C4\u05C5\u05C7]/g;
 10→  return text.replace(nikudRegex, '');
 11→};
 12→
 13→// Implements the classic Kri/Ksiv processing from the legacy logic
 14→// withNikud = false:
 15→//  - replace maqaf '־' with a space (twice to catch chains)
 16→//  - remove any content in <...> (KSIV) and any leftover non-Hebrew chars
 17→//  - compress multiple spaces
 18→// withNikud = true:
 19→//  - remove content in [...] (KRI) and the <> delimiters for KSIV
 20→export const processKriKsiv = (txt: string, withNikud: boolean): string => {
 21→  if (!withNikud) {
 22→    return txt
 23→      .replace(/־/g, ' ') // maqaf to space
 24→      .replace(/<.+?>/g, '') // remove KSIV
 25→      .replace(/\s{2,}/g, ' ') // collapse spaces
 26→  .replace(/[^ \u05D0-\u05EA]/g, '') // keep only Alef–Tav + space
 27→      .trim();
 28→  }
 29→  // with nikud: remove KRI (inside square brackets) and strip <>
 30→  return txt
 31→    .replace(/\[[\s\S]*?\]/g, '') // remove KRI
 32→    .replace(/[<>]/g, ''); // drop KSIV brackets only
 33→};
 34→
 35→// Process Hebrew text for display with proper spacing and formatting
 36→export const processHebrewText = (
 37→  fragments: string[],
 38→  withNikud: boolean = true,
 39→  _wordGap: number = 0,
 40→  layout?: string
 41→): string[] => {
 42→  // Special case: single fragment with satum layout should split into individual words
 43→  if (fragments.length === 1 && layout?.includes('satum')) {
 44→    const kriKsiv = processKriKsiv(fragments[0], withNikud);
 45→    const processed = withNikud ? kriKsiv : removeNikud(kriKsiv);
 46→    return processed.split(' ').filter(Boolean);
 47→  }
 48→  
 49→  // Default case: apply kri/ksiv handling and optionally remove nikud
 50→  return fragments.map(fragment => {
 51→    const kriKsiv = processKriKsiv(fragment, withNikud);
 52→    return withNikud ? kriKsiv : removeNikud(kriKsiv);
 53→  });
 54→};
