 62→export function numberToHebrewLetters(n: number): string {
 63→  if (n <= 0) return '';
 64→  // Basic gematria: handle up to 400+ with combinations; keep simple but general
 65→  const units: Record<number, string> = {
 66→    1:'א',2:'ב',3:'ג',4:'ד',5:'ה',6:'ו',7:'ז',8:'ח',9:'ט'
 67→  };
 68→  const tens: Record<number, string> = {
 69→    10:'י',20:'כ',30:'ל',40:'מ',50:'נ',60:'ס',70:'ע',80:'פ',90:'צ'
 70→  };
 71→  const hundreds: Record<number, string> = {
 72→    100:'ק',200:'ר',300:'ש',400:'ת'
 73→  };
 74→
 75→  let res = '';
 76→  let remaining = n;
 77→  // Hundreds
 78→  const hundredsKeys = [400,300,200,100];
 79→  for (const h of hundredsKeys) {
 80→    while (remaining >= h) {
 81→      res += hundreds[h];
 82→      remaining -= h;
 83→    }
 84→  }
 85→  // Tens
 86→  const tensKeys = [90,80,70,60,50,40,30,20,10];
 87→  for (const t of tensKeys) {
 88→    while (remaining >= t) {
 89→      res += tens[t];
 90→      remaining -= t;
 91→    }
 92→  }
 93→  // Units
 94→  if (remaining > 0) res += units[remaining] || '';
 95→  return res;
 96→}
