101→export const lehaderesLetters: LehaderesLetter[] = [
102→  { os: 'ל', r1: String.fromCharCode(0x05F5), r2: String.fromCharCode(0x05F6) },
103→  { os: 'ה', r1: String.fromCharCode(0x05F8), r2: String.fromCharCode(0x05F9) },
104→  { os: 'ד', r1: String.fromCharCode(0x05FA), r2: String.fromCharCode(0x05FB) },
105→  { os: 'ר', r1: String.fromCharCode(0x05FC), r2: String.fromCharCode(0x05FD) },
106→  { os: 'ת', r1: String.fromCharCode(0x05FE), r2: String.fromCharCode(0x05FF) }
107→];
108→
109→export const isLehaderesChar = (ch: string) =>
110→  lehaderesLetters.some(l => l.os === ch);
111→
112→export const makeStretched = (chr: string, widthUnits: number): string => {
113→  const mapping = lehaderesLetters.find(l => l.os === chr);
114→  if (!mapping) return chr;
115→  const count = Math.max(1, Math.round(widthUnits));
116→  return mapping.r1 + stretchBar.repeat(count) + mapping.r2;
117→};
