  3→/**
  4→ * Data loader utility for Torah text
  5→ * This handles loading the full Tikkun data from various sources
  6→ */
  7→
  8→// For production, you would load this from an API or external service
  9→export class TikkunDataLoader {
 10→  private static instance: TikkunDataLoader;
 11→  private cachedData: Amud[] | null = null;
 12→  private loading: boolean = false;
 13→
 14→  static getInstance(): TikkunDataLoader {
 15→    if (!TikkunDataLoader.instance) {
 16→      TikkunDataLoader.instance = new TikkunDataLoader();
 17→    }
 18→    return TikkunDataLoader.instance;
 19→  }
 20→
 21→  /**
 22→   * Load Tikkun data from the original JavaScript file
 23→   * In production, this would be replaced with an API call or database query
 24→   */
 25→  async loadFullData(): Promise<Amud[]> {
 26→    if (this.cachedData) {
 27→      return this.cachedData;
 28→    }
 29→
 30→    if (this.loading) {
 31→      // Wait for existing load to complete
 32→      return new Promise((resolve) => {
 33→        const checkLoading = () => {
 34→          if (!this.loading && this.cachedData) {
 35→            resolve(this.cachedData);
 36→          } else {
 37→            setTimeout(checkLoading, 100);
 38→          }
 39→        };
 40→        checkLoading();
 41→      });
 42→    }
 43→
 44→    this.loading = true;
 45→    
 46→    try {
 47→      // In a real application, you might:
 48→      // 1. Fetch from an API: await fetch('/api/tikkun-data')
 49→      // 2. Load from a database
 50→      // 3. Stream large data in chunks
 51→      
 52→      // For now, we'll try to load from the backup file if it exists
 53→      const response = await fetch('/backup/tikun.js');
 54→      if (response.ok) {
 55→        const jsText = await response.text();
 56→        // Parse the JavaScript variable declaration
 57→        const dataMatch = jsText.match(/var tikkun = (\[.*\]);/);
 58→        if (dataMatch) {
 59→          this.cachedData = JSON.parse(dataMatch[1]);
 60→          return this.cachedData!;
 61→        }
 62→      }
 63→      
 64→      // Fallback to sample data
 65→      const { tikkunData } = await import('../data/tikkunData');
 66→      this.cachedData = tikkunData;
 67→      return this.cachedData;
 68→      
 69→    } catch (error) {
 70→      console.error('Failed to load full Tikkun data:', error);
 71→      // Return sample data as fallback
 72→      const { tikkunData } = await import('../data/tikkunData');
 73→      this.cachedData = tikkunData;
 74→      return this.cachedData;
 75→    } finally {
 76→      this.loading = false;
 77→    }
 78→  }
 79→
 80→  /**
 81→   * Get a specific amud by number
 82→   */
 83→  async getAmud(amudNumber: number): Promise<Amud | null> {
 84→    const data = await this.loadFullData();
 85→    return data.find(amud => amud.amud === amudNumber) || null;
 86→  }
 87→
 88→  /**
 89→   * Get amudim in a range
 90→   */
 91→  async getAmudRange(start: number, end: number): Promise<Amud[]> {
 92→    const data = await this.loadFullData();
 93→    return data.filter(amud => amud.amud >= start && amud.amud <= end);
 94→  }
 95→
 96→  /**
 97→   * Get total number of amudim
 98→   */
 99→  async getTotalAmudim(): Promise<number> {
100→    const data = await this.loadFullData();
101→    return data.length;
102→  }
103→
104→  /**
105→   * Clear cached data (useful for memory management)
106→   */
107→  clearCache(): void {
108→    this.cachedData = null;
109→  }
110→}
111→
112→// Export singleton instance
113→export const tikkunDataLoader = TikkunDataLoader.getInstance();
